// EndpointSource provides data for XDS server from different data sources in the agent.
type EndpointSource struct {
	k8sCiliumEndpointsWatcher CiliumEndpointsWatcher
	sp                        *StreamProcessor
}

func NewEndpointSource(k CiliumEndpointsWatcher, sp *StreamProcessor) *EndpointSource {
	return &EndpointSource{
		k8sCiliumEndpointsWatcher: k,
		sp:                        sp,
	}
}

// Interface different data sources need to implement for usage with StreamProcessor.
type EndpointEventSource interface {
	// SubscribeToEndpointEvents subscribes to Endpoint events. All events that
	// arrive before the initial Sync event are buffered into a single
	// EndpointEventCollection and sent on syncCh. After the Sync event,
	// subsequent events are forwarded individually to the StreamProcessor's
	// endpointRecv channel. syncCh is closed when the subscription ends.
	SubscribeToEndpointEvents(ctx context.Context, syncCh chan<- EndpointEventCollection)
}

func NewStreamProcessor(params *StreamProcessorParams) *StreamProcessor {
	sp := &StreamProcessor{
		stream:                 params.Stream,
		streamRecv:             params.StreamRecv,
		endpointRecv:           params.EndpointEventRecv,
		log:                    params.Log,
		expectedNonce:          make(map[string]struct{}),
		db:                     params.DB,
		enrolledNamespaceTable: params.EnrolledNamespaceTable,
	}
	sp.endpointSource = NewEndpointSource(params.K8sCiliumEndpointsWatcher, sp)
	return sp
}

// isNamespaceEnrolled reports whether the given namespace is enrolled in ztunnel
// mTLS. When no enrolled namespace table is configured, all namespaces are
// treated as enrolled.
func (sp *StreamProcessor) isNamespaceEnrolled(ns string) bool {
	if sp.db == nil || sp.enrolledNamespaceTable == nil {
		return true
	}
	txn := sp.db.ReadTxn()
	_, _, found := sp.enrolledNamespaceTable.Get(txn, table.EnrolledNamespacesNameIndex.Query(ns))
	return found
