func (es *EndpointSource) handleCESUpsert(ces *v2alpha1.CiliumEndpointSlice, cesCache map[resource.Key]map[string]*types.CiliumEndpoint, key resource.Key) EndpointEventCollection {
	oldCEPs := cesCache[key]
	if oldCEPs == nil {
		oldCEPs = make(map[string]*types.CiliumEndpoint)
	}

	newCEPs := convertCESToEndpointMap(ces)
	added, updated, removed := computeEndpointDiff(oldCEPs, newCEPs)

	collection := EndpointEventCollection{}
	collection.AppendEndpoints(REMOVED, removed)
	collection.AppendEndpoints(CREATE, added)
	collection.AppendEndpoints(CREATE, updated) // Updates are treated as CREATE

	// Update cache
	cesCache[key] = newCEPs

	return collection
}

// handleCESDelete processes a delete event for a CiliumEndpointSlice, returning
// an EndpointEventCollection with REMOVED events for all endpoints in the slice.
func (es *EndpointSource) handleCESDelete(ces *v2alpha1.CiliumEndpointSlice, cesCache map[resource.Key]map[string]*types.CiliumEndpoint, key resource.Key) EndpointEventCollection {
	endpoints := convertCESToEndpointMap(ces)
	endpointList := make([]*types.CiliumEndpoint, 0, len(endpoints))
	for _, ep := range endpoints {
		endpointList = append(endpointList, ep)
	}

	collection := EndpointEventCollection{}
	collection.AppendEndpoints(REMOVED, endpointList)

	delete(cesCache, key)

	return collection
}

// forwardEvents forwards each event in the collection to the StreamProcessor's
// endpointRecv channel, aborting if the context is canceled.
func (es *EndpointSource) forwardEvents(ctx context.Context, collection EndpointEventCollection) {
	for _, ev := range collection {
		select {
		case es.sp.endpointRecv <- ev:
		case <-ctx.Done():
			return
		}
	}
}

