	// Disenroll all endpoints in this namespace
	endpoints := ops.endpointManager.GetEndpointsByNamespace(ns.Name)
	for _, ep := range endpoints {
		if ep.GetContainerNetnsPath() == "" || isZtunnelPod(ep) {
