// emitEndpointEvents emits an endpoint event of the given type to the endpoint
// event channel for every endpoint in the given namespace. Endpoints are sourced
// from either the CiliumEndpoint or CiliumEndpointSlice resource depending on
// whether CiliumEndpointSlice mode is enabled.
func (ops *EnrollmentReconciler) emitEndpointEvents(ctx context.Context, namespace string, eventType xds.EndpointEventType) {
	if ops.endpointEventCh == nil {
		return
	}

	eps, err := ops.listEndpointsInNamespace(ctx, namespace)
	if err != nil {
		ops.logger.Error("Failed to list endpoints for namespace",
			logfields.K8sNamespace, namespace,
			logfields.Error, err,
		)
		return
	}

	for _, ep := range eps {
		ops.endpointEventCh <- &xds.EndpointEvent{
			Type:           eventType,
			CiliumEndpoint: ep,
		}
	}
}

// listEndpointsInNamespace returns all CiliumEndpoints belonging to the given
// namespace, reading from the CiliumEndpointSlice resource when CiliumEndpointSlice
// mode is enabled and the CiliumEndpoint resource otherwise.
func (ops *EnrollmentReconciler) listEndpointsInNamespace(ctx context.Context, namespace string) ([]*types.CiliumEndpoint, error) {
	if option.Config.EnableCiliumEndpointSlice {
		if ops.ciliumEndpointSliceResource == nil {
			return nil, nil
		}
		store, err := ops.ciliumEndpointSliceResource.Store(ctx)
		if err != nil {
			return nil, fmt.Errorf("failed to get CiliumEndpointSlice store: %w", err)
		}
		var eps []*types.CiliumEndpoint
		for _, ces := range store.List() {
			if ces.Namespace != namespace {
				continue
			}
			for i := range ces.Endpoints {
				eps = append(eps, k8s.ConvertCoreCiliumEndpointToTypesCiliumEndpoint(&ces.Endpoints[i], ces.Namespace))
			}
		}
		return eps, nil
	}

	if ops.ciliumEndpointResource == nil {
		return nil, nil
	}
	store, err := ops.ciliumEndpointResource.Store(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get CiliumEndpoint store: %w", err)
	}
	var eps []*types.CiliumEndpoint
	for _, cep := range store.List() {
		if cep.Namespace != namespace {
			continue
		}
		eps = append(eps, cep)
	}
	return eps, nil
