// registerStream adds a stream processor to the set of active streams that
// receive broadcast endpoint events.
func (x *Server) registerStream(sp *StreamProcessor) {
	x.streamsMu.Lock()
	defer x.streamsMu.Unlock()
	x.streams[sp] = struct{}{}
}

// unregisterStream removes a stream processor from the set of active streams.
func (x *Server) unregisterStream(sp *StreamProcessor) {
	x.streamsMu.Lock()
	defer x.streamsMu.Unlock()
	delete(x.streams, sp)
}

// broadcastEndpointEvents drains the shared endpoint event channel and forwards
// each event to every active stream processor. Sends are non-blocking to avoid
// stalling on a slow stream.
func (x *Server) broadcastEndpointEvents() {
	if x.endpointEventCh == nil {
		return
	}
	for ev := range x.endpointEventCh {
		x.streamsMu.Lock()
		for sp := range x.streams {
			select {
			case sp.endpointRecv <- ev:
			default:
				x.log.Warn("dropping endpoint event, stream receive buffer full")
			}
		}
		x.streamsMu.Unlock()
	}
